package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
)

var allowedTypes = map[string]bool{"image/jpeg": true, "image/png": true, "image/gif": true}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/uploads", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" { http.NotFound(w, r); return }
		r.ParseMultipartForm(32 << 20)
		files := r.MultipartForm.File["files"]
		var result []map[string]interface{}
		for _, fh := range files {
			mime := fh.Header.Get("Content-Type")
			if !allowedTypes[strings.Split(mime, ";")[0]] {
				w.WriteHeader(400)
				json.NewEncoder(w).Encode(map[string]string{"error": "Only images allowed"})
				return
			}
			f, _ := fh.Open()
			data, _ := io.ReadAll(f)
			f.Close()
			result = append(result, map[string]interface{}{"name": fh.Filename, "size": len(data), "type": mime})
		}
		json.NewEncoder(w).Encode(result)
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}

