package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sync"
)

type FileInfo struct {
	Name string `json:"name"`
	Size int    `json:"size"`
	Type string `json:"type"`
}

var (
	uploadedFiles []FileInfo
	mu            sync.Mutex
)

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/uploads", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch r.Method {
		case "POST":
			r.ParseMultipartForm(1 << 20)
			files := r.MultipartForm.File["files"]
			var infos []FileInfo
			for _, fh := range files {
				f, _ := fh.Open()
				data, _ := io.ReadAll(f)
				f.Close()
				infos = append(infos, FileInfo{Name: fh.Filename, Size: len(data), Type: fh.Header.Get("Content-Type")})
			}
			mu.Lock()
			uploadedFiles = append(uploadedFiles, infos...)
			mu.Unlock()
			json.NewEncoder(w).Encode(infos)
		case "GET":
			mu.Lock()
			json.NewEncoder(w).Encode(uploadedFiles)
			mu.Unlock()
		}
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}
